#!/usr/bin/env python3
"""Writes sources/facts.json: every fact the lessons may cite, with the strings that prove it.

Each fact: id, src (registry id), anchor (section or page locator), claim (our paraphrase, which is what
a lesson sentence may say), check (strings that must appear in the source text), mod ("py" or "ml").
Run `python3 sources/build_facts.py && python3 tools/verify_facts.py`.
A claim must say no more than its check strings and anchor support. If you cannot support it, delete it.
"""
import json, pathlib
F = []
COUNT = {"py": 0, "ml": 0}
def f(src, anchor, claim, check, mod):
    COUNT[mod] += 1
    F.append(dict(id=f"{mod}-{COUNT[mod]:03d}", src=src, anchor=anchor, claim=claim, check=check, mod=mod))
def retired(mod):
    """A fact that was removed. Keeps later IDs stable so lesson citations do not shift."""
    COUNT[mod] += 1
def py(*a): f(*a, "py")
def ml(*a): f(*a, "ml")

